import base64
import pathlib
import os

# base64 content generated in previous step, no double quotes inside
files_b64 = {
    'package.json': '',
    'vite.config.js': 'aW1wb3J0IHsgZGVmaW5lQ29uZmlnIH0gZnJvbSAndml0ZSc7CmV4cG9ydCBkZWZhdWx0IGRlZmluZUNvbmZpZyh7CiAgY2xlYXJTY3JlZW46IGZhbHNlLAogIHNlcnZlcjogeyBwb3J0OiAxNDIwLCBzdHJpY3RQb3J0OiB0cnVlIH0sCiAgZW52UHJlZml4OiBbJ1ZJVEVfJywgJ1RBVVJJXyddLAogIGJ1aWxkOiB7IHRhcmdldDogJ2VzbmV4dCcsIG1pbmlmeTogZmFsc2UgfQp9KTsK',
    'src-tauri/tauri.conf.json': '',
    'src-tauri/Cargo.toml': '',
    'src-tauri/src/main.rs': '',
    'src/index.html': '',
    'README.md': ''
}

base_dir = pathlib.Path(__file__).parent
for rel_path, b64_str in files_b64.items():
    full_path = base_dir / rel_path
    full_path.parent.mkdir(parents=True, exist_ok=True)
    data = base64.b64decode(b64_str)
    full_path.write_bytes(data)
    print(f'wrote {full_path} ({len(data)} bytes)')

# also need src-tauri/src dir
(pathlib.Path(__file__).parent / 'src-tauri' / 'src').mkdir(parents=True, exist_ok=True)

# create icons placeholder dir to avoid tauri build error if missing
icons_dir = base_dir / 'src-tauri' / 'icons'
icons_dir.mkdir(parents=True, exist_ok=True)
# create empty placeholder if not exists, tauri needs at least one icon but we can skip for dev
print('Tauri A scheme generated. Now run: cd tauri-app && npm install && npm run tauri dev')
